// scripts/OLSD134R/file-generator.js
// Prepare input data for the OLSD134R report.
// Unlike OLSDB024, this report has no input file of its own.
//
// OLSD134R reads data written by OLSDB009 into dwh_temp_txn.
// Therefore, preparation means creating and processing input for OLSDB009:
//
//   OLSTXN input (generated by OLSDB009's generator)
//        -> copy to src\ -> upload via SFTP -> run ./OLSDB009
//        -> dwh_temp_txn contains rejected txn_type='01' records
//           (error_code IS NOT NULL), which become OLSD134R's expected data
//
// After the batch finishes, the script queries dwh_temp_txn to:
//   - verify that rejected transactions were created
//   - capture Batch ID, Process Date, Product Account Number, Error Code, and Error Message
//     from the database instead of hard-coding them
//
// Run manually: node scripts/OLSD134R/file-generator.js
// Automatically called by test.beforeAll in test-runner.spec.js

import fs from 'fs-extra';
import path from 'path';
import { exec } from 'child_process';
import { promisify } from 'util';
import { fileURLToPath } from 'url';
import pg from 'pg';
import { generateTestCase } from '../OLSDB009/file-generator.js';
import {
  CONFIG, SCHEMA, ADJUSTMENT_SOURCE, CUTOFF_MODULE_IDS, TXN_TYPE_REDEMPTION, FILE_ID, TXN_TYPE_FILE,
  HD_RECEIVING_SYSTEM,
} from './test-data.js';
import { stagingPath } from './file-naming.js';

const execAsync = promisify(exec);
const __dirname = path.dirname(fileURLToPath(import.meta.url));

// ============ HELPER FUNCTIONS ============
function log(message, data = {}) {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${message}`, Object.keys(data).length ? data : '');
}

// child_process errors may include the full command, including -pw <password>.
// Prevent credentials from appearing in logs or console output.
function maskSecret(text) {
  let out = String(text ?? '');
  for (const secret of [CONFIG.putty.password, CONFIG.winscp.password]) {
    if (secret && secret.length >= 3) out = out.split(secret).join('****');
  }
  return out;
}

// -batch and -hostkey are required. Without them, plink may wait for the
// "Store key in cache? (y/n)" prompt and hang because no stdin is available.
function plinkCommand(remoteCommand) {
  return `"${CONFIG.putty.path}" ` +
    `-batch ` +
    `-hostkey "${CONFIG.putty.hostKey}" ` +
    `-ssh ${CONFIG.putty.username}@${CONFIG.putty.host} ` +
    `-pw ${CONFIG.putty.password} ` +
    `"${remoteCommand}"`;
}

/**
 * Run one batch on the server: cd <scriptPath> && ./<batchId>.
 * Throw immediately if the command cannot run, so this is not confused with
 * a batch that ran but produced no data.
 */
export async function runRemoteBatch(batchId, testCase = batchId) {
  const command = `cd ${CONFIG.batch.scriptPath} && ./${batchId}`;
  log(`[${testCase}] Run batch: ${command}`);

  try {
    const { stdout, stderr } = await execAsync(plinkCommand(command), {
      timeout: CONFIG.batch.timeout,
      maxBuffer: 1024 * 1024 * 10,
    });
      log(`[${testCase}] ${batchId} finished`);
    return { success: true, stdout, stderr };
  } catch (error) {
    throw new Error(
      `[${testCase}] Batch ${batchId} could not run: ${maskSecret(error.message)}\n` +
      `(check VPN, plink.exe, host key, or ${CONFIG.batch.scriptPath}/${batchId})\n` +
      `Hint: exit code 20 + "batch status: STOPPED" usually means the file was rejected. For OLSDB009\n` +
      `the real reason is in <${CONFIG.winscp.remotePath}>OLSDB009_<pid>_<batchdate>.err and OLSTXN-*.rej\n` +
      `(e.g. "CreateDate ... is before last run date of ..." when the dev control date was pushed to a future day).`
    );
  }
}

async function uploadFiles(fileNames, testCase = 'OLSDB009') {
  for (const name of fileNames) {
    const command = `"${CONFIG.winscp.path}" /command ` +
      `"option batch abort" ` +
      `"option confirm off" ` +
      `"open sftp://${CONFIG.winscp.username}:${CONFIG.winscp.password}@${CONFIG.winscp.host}/" ` +
      `"cd ${CONFIG.winscp.remotePath}" ` +
      `"put ""${stagingPath(name)}""" ` +
      `"exit"`;

    try {
      await execAsync(command, { timeout: 60000, maxBuffer: 1024 * 1024 * 10 });
      log(`[${testCase}] Upload OK: ${name}`);
    } catch (error) {
      throw new Error(`[${testCase}] Upload failed ${name}: ${maskSecret(error.message)}`);
    }
  }
}

/** Run a read-only command on the server, such as ls, grep, or wc. */
async function executeRemoteCommand(command, testCase = 'OLSD134R') {
  const { stdout } = await execAsync(plinkCommand(command), {
    timeout: 120000,
    maxBuffer: 1024 * 1024 * 10,
  });
  return stdout;
}

// ============ DATABASE HELPERS ============
// Define DB helpers locally because scripts/database_helper.js is not an importable module.
// It depends on global variables and does not export its functions.
// Keep the helpers local to this generator.
async function getDbConnection() {
  const client = new pg.Client({
    host: CONFIG.database.host,
    port: CONFIG.database.port,
    user: CONFIG.database.username,
    password: CONFIG.database.password,
    database: CONFIG.database.database,
  });
  await client.connect();
  return client;
}

async function executeDbQuery(query, params = [], testCase = 'OLSD134R') {
  const client = await getDbConnection();
  try {
    const result = await client.query(query, params);
    return result.rows;
  } catch (error) {
    throw new Error(`[${testCase}] DB query failed: ${error.message}\nSQL: ${query.trim()}`);
  } finally {
    await client.end();
  }
}

// Files already imported successfully will be rejected with BE051 if uploaded again,
// so they must be skipped (AGENTS.md section 4.1: file names/sequences are daily-use resources).
//
// Rejected records are not considered imported: the batch removes the file from the input
// directory and leaves only a .rej file. On dev, OLSTXN-OLS-20260915-01.dat was rejected
// with BE301 (CreateDate < last run date), while batch_resource recorded process_status='R'.
// After the control date is corrected, the same file name can be uploaded again for verification.
// Therefore, records with status 'R' are excluded.
async function findAlreadyImportedNames(fileNames) {
  const rows = await executeDbQuery(
    `SELECT DISTINCT logical_filename FROM ${SCHEMA}.batch_resource
      WHERE logical_filename = ANY($1)
        AND coalesce(process_status, '') <> 'R'`,
    [fileNames],
    'OLSDB009'
  );
  return rows.map((r) => r.logical_filename);
}

// ============ DATE HELPERS ============
function toYmd(value) {
  if (value instanceof Date) {
    return `${value.getFullYear()}${String(value.getMonth() + 1).padStart(2, '0')}${String(value.getDate()).padStart(2, '0')}`;
  }
  const s = String(value ?? '').trim();
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${m[1]}${m[2]}${m[3]}` : s.slice(0, 10).replace(/-/g, '');
}

function toIsoDate(value) {
  const ymd = toYmd(value);
  return `${ymd.slice(0, 4)}-${ymd.slice(4, 6)}-${ymd.slice(6, 8)}`;
}

function shiftIsoDate(isoDate, days) {
  const [y, m, d] = isoDate.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

function normalizeCutOff(value) {
  if (value instanceof Date) {
    return `${String(value.getHours()).padStart(2, '0')}:${String(value.getMinutes()).padStart(2, '0')}:${String(value.getSeconds()).padStart(2, '0')}`;
  }
  const s = String(value ?? '').trim();
  const m = s.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (m) return `${String(m[1]).padStart(2, '0')}:${m[2]}:${m[3] || '00'}`;
  const digits = s.match(/^(\d{2})(\d{2})(\d{2})$/);
  return digits ? `${digits[1]}:${digits[2]}:${digits[3]}` : s;
}

/**
 * Load the batch date and reporting window from the database:
 *   batch date      : ols_schema.batch_date.batch_date
 *   current cut-off: ols_schema.oe_cutofftime_control (module_id OLSDR134)
 *   window          : (BD - 1 day) + cut-off  ->  BD + cut-off
 *
 * The report filters dwh_temp_txn.process_date rather than transaction date/time fields.
 * fromDate and toDate are returned for expected-data queries.
 */
/**
 * Step 0 - set batch_date to CURRENT_DATE before running OLSDB009.
 *
 * OLSDB009 writes dwh_temp_txn.process_date using the processing date, while OLSD134R
 * reads data by batch date and process_date window. Set batch_date to the run date so new
 * data falls inside the report window. Set OLSD134R_SKIP_BATCHDATE_UPDATE=1 to skip the DB update.
 */
export async function updateBatchDate(testCase = 'OLSD134R') {
  if (process.env.OLSD134R_SKIP_BATCHDATE_UPDATE === '1') {
    log(`[${testCase}] Skip batch_date update (OLSD134R_SKIP_BATCHDATE_UPDATE=1)`);
    return null;
  }

  const sel = `SELECT record_no,
                      to_char(batch_date, 'YYYY-MM-DD')      AS batch_date,
                      to_char(processing_date, 'YYYY-MM-DD') AS processing_date
                 FROM ${SCHEMA}.batch_date ORDER BY record_no DESC LIMIT 1`;
  const before = await executeDbQuery(sel, [], testCase);

  await executeDbQuery(
    `UPDATE ${SCHEMA}.batch_date
        SET batch_date      = CURRENT_DATE,
            processing_date = CURRENT_DATE - 1,
            last_update_date = now(),
            last_update_by   = $1
      WHERE record_no = (SELECT MAX(record_no) FROM ${SCHEMA}.batch_date)`,
    [testCase],
    testCase
  );

  const after = await executeDbQuery(sel, [], testCase);
  log(`[${testCase}] Update batch_date: ${before[0] ? before[0].batch_date : 'n/a'} -> ` +
    `${after[0] ? after[0].batch_date : 'n/a'}`);
  return { before: before[0] || null, after: after[0] || null };
}

export async function getBatchContext(testCase = 'OLSD134R') {
  const batchRows = await executeDbQuery(
    `SELECT batch_date FROM ${SCHEMA}.batch_date ORDER BY batch_date DESC LIMIT 1`,
    [],
    testCase
  );
  if (!batchRows.length) {
    throw new Error(`[${testCase}] Table ${SCHEMA}.batch_date has no row.`);
  }

  const batchDate = toIsoDate(batchRows[0].batch_date);

  // Column names verified on dev through information_schema:
  //   control_cutoff_time  character varying  -> '235959' (module cut-off time)
  //   current_cutoff_time  timestamp          -> cut-off timestamp from the latest run
  // Use the actual current_cutoff_time column name defined in the database.
  const cutoffRows = await executeDbQuery(
    `SELECT module_id, current_cutoff_time, control_cutoff_time
       FROM ${SCHEMA}.oe_cutofftime_control WHERE module_id = ANY($1)`,
    [CUTOFF_MODULE_IDS],
    testCase
  );

  let picked = null;
  for (const moduleId of CUTOFF_MODULE_IDS) {
    picked = cutoffRows.find((r) => String(r.module_id).trim() === moduleId) || null;
    if (picked) break;
  }

  // The cut-off is used to log the data window; the report filters by process_date date range.
  // A missing cut-off row therefore does not fail data preparation.
  let cutOffTime = '23:59:59';
  let cutOffModuleId = '(no cut-off row)';
  if (picked) {
    cutOffModuleId = String(picked.module_id).trim();
    cutOffTime = normalizeCutOff(picked.control_cutoff_time || picked.current_cutoff_time) || '23:59:59';
    if (cutOffModuleId !== CUTOFF_MODULE_IDS[0]) {
      log(`[${testCase}] ⚠️ No cut-off row for '${CUTOFF_MODULE_IDS[0]}', using '${cutOffModuleId}'.`);
    }
  } else {
    log(`[${testCase}] ⚠️ No cut-off row for ${CUTOFF_MODULE_IDS.join(' / ')} in ` +
      `${SCHEMA}.oe_cutofftime_control - using default 23:59:59.`);
  }

  return {
    batchDate,
    batchDateYmd: toYmd(batchDate),
    cutOffTime,
    cutOffModuleId,
    fromDate: shiftIsoDate(batchDate, -1),
    toDate: batchDate,
    windowStart: `${shiftIsoDate(batchDate, -1)} ${cutOffTime}`,
    windowEnd: `${batchDate} ${cutOffTime}`,
  };
}

// ============ DWH_TEMP_TXN (REPORT DATA SOURCE) ============
// Match the report filter: TXN_TYPE='01' AND ERROR_CODE IS NOT NULL within the process_date window.
const REJECTED_REDEMPTION_WHERE = `dtt.txn_type = $1
    AND dtt.error_code IS NOT NULL
    AND dtt.process_date::date >  $2::date
    AND dtt.process_date::date <= $3::date`;

/**
 * Return rejected redemption records in the current batch window.
 *
 * OLSDR134 does not display transactions with Process_date (DWH_TEMP_TXN)
 * <= the last cut-off time, so add that condition when lastCutoffTime is available.
 */
export async function fetchRejectedRedemptions(ctx, testCase = 'OLSDB009', lastCutoffTime = null) {
  const cutoffClause = lastCutoffTime ? '\n      AND dtt.process_date > $4::timestamp' : '';
  const sql = `SELECT dtt.batch_id, dtt.prod_acct_nbr, dtt.txn_type, dtt.error_code, dtt.error_message,
      dtt.maintenance_date, dtt.process_date, dtt.branch_id, dtt.txn_amt, dtt.txn_sign
    FROM ${SCHEMA}.dwh_temp_txn dtt
    WHERE ${REJECTED_REDEMPTION_WHERE}${cutoffClause}
    ORDER BY dtt.batch_id, dtt.maintenance_date`;

  return executeDbQuery(
    sql,
    lastCutoffTime
      ? [TXN_TYPE_REDEMPTION, ctx.fromDate, ctx.toDate, lastCutoffTime]
      : [TXN_TYPE_REDEMPTION, ctx.fromDate, ctx.toDate],
    testCase
  );
}

/**
 * Return rejected redemption records written by OLSDB009 for the uploaded OLSTXN file.
 * This verifies that OLSDB009 created the rejected transactions without depending on
 * batch_date, which may differ from the run date.
 */
export async function fetchRejectedRedemptionsByFileName(fileNames, testCase = 'OLSDB009') {
  const sql = `SELECT dtt.file_name, dtt.batch_id, dtt.prod_acct_nbr, dtt.txn_type, dtt.error_code,
      dtt.error_message, dtt.maintenance_date, dtt.process_date, dtt.branch_id, dtt.txn_amt,
      dtt.txn_sign, dtt.process_status
    FROM ${SCHEMA}.dwh_temp_txn dtt
    WHERE dtt.file_name = ANY($1::text[])
      AND dtt.error_code IS NOT NULL
    ORDER BY dtt.id`;

  return executeDbQuery(sql, [fileNames], testCase);
}

// ============ DATA PREPARATION STEPS ============
/**
 * Set the transaction date fields in the generated OLSTXN file to the batch date.
 *
 * Test data must represent transactions for the batch date under test, not the run date
 * (the OLSDB009 generator always sets txnTranDate/txnSrcPostDate to getCurrentDate()).
 *
 * Important: these fields do not determine dwh_temp_txn.process_date. On dev, the file
 * OLSTXN-OLS-20260915-01.dat had DT txn_date=20260915, but its dwh_temp_txn record had
 * process_date='2026-09-20 17:00', the file processing date. OLSD134R filters by process_date,
 * so its data window depends on batch_date, not these two transaction-date fields.
 */
function setDetailDates(content, dateYmd) {
  let changed = 0;
  const lines = String(content).split(/\r?\n/).map((line) => {
    if (!line.startsWith('DT|')) return line;
    const cells = line.split('|'); // cells[0] = 'DT', cells[1..47] = the 47 DT fields
    if (cells.length > 12) {
      cells[10] = dateYmd; // txnTranDate
      cells[12] = dateYmd; // txnSrcPostDate
      changed += 1;
    }
    return cells.join('|');
  });
  return { content: lines.join('\r\n'), changed };
}

/**
 * Set dates in the OLSTXN HD record.
 *
 * Mapping verified on dev (batch_header):
 *   HD cell[3] (createDate)            -> batch_header.source_create_date
 *   HD cell[4] (batchDate, as stored) -> batch_header.source_batch_date
 *   HD cell[5] (fileNumber)            -> batch_header.file_number
 *
 * Batch rules: CreateDate must be >= the last run date (MAX source_create_date), HD batch date
 * must be >= the current MAX(source_batch_date), and each new file must use a unique batch date
 * (see batch_header.line).
 */
function setHeaderDates(content, { createDate, batchDate, fileNumber, receivingSystem }) {
  const lines = String(content).split(/\r?\n/).map((line) => {
    if (!line.startsWith('HD|')) return line;
    const cells = line.split('|');
    if (cells.length > 5) {
      // HD cell 2 = receiving system (OLS for the main file, SICS for the SICS input file)
      if (receivingSystem) cells[2] = receivingSystem;
      cells[3] = createDate; // createDate  -> source_create_date
      cells[4] = batchDate;  // batchDate   -> source_batch_date
      if (fileNumber) cells[5] = fileNumber; // fileNumber -> batch_header.file_number
    }
    return cells.join('|');
  });
  return lines.join('\r\n');
}

/**
 * Get the next file number for (file_id + createDate).
 *
 * Dev evidence (.rej file): "BE302 | File Id with number OLSTXN@0001 is duplicated
 * with same date 2026-09-21". The batch checks (file_id, file_number, source_create_date),
 * not only the file name, so the HD file number must be unused for the given createDate.
 */
async function getNextFileNumber(isoCreateDate, testCase = 'OLSDB009') {
  const rows = await executeDbQuery(
    `SELECT MAX(NULLIF(regexp_replace(file_number, '\\D', '', 'g'), '')::bigint) AS max_no
       FROM ${SCHEMA}.batch_header
      WHERE file_id = $1 AND source_create_date::date = $2::date`,
    [FILE_ID, isoCreateDate],
    testCase
  );
  const maxNo = rows.length && rows[0].max_no ? Number(rows[0].max_no) : 0;
  return maxNo + 1;
}

/** Check whether a file name already exists in the ledger; any status causes BE051. */
async function isFileNameUsed(fileName, testCase = 'OLSDB009') {
  const rows = await executeDbQuery(
    `SELECT 1 FROM ${SCHEMA}.batch_resource WHERE logical_filename = $1 LIMIT 1`,
    [fileName],
    testCase
  );
  return rows.length > 0;
}

/**
 * Get a valid pool_id from ols_schema.pool_definition (status 'A').
 * txn_type='01' (redemption) requires a Pool Id; otherwise the batch returns
 * BE662 "Pool Id can not be blank with transaction type as adjustment".
 * Prefer a pool matching the account currency, then fall back to the first active pool.
 */
export async function getPoolId(currencyCode = null, testCase = 'OLSD134R') {
  let rows = await executeDbQuery(
    `SELECT pool_id, currency_code, status FROM ${SCHEMA}.pool_definition
      WHERE status = 'A' AND ($1::text IS NULL OR currency_code = $1)
      ORDER BY pool_id LIMIT 1`,
    [currencyCode],
    testCase
  );

  if (!rows.length) {
    rows = await executeDbQuery(
      `SELECT pool_id, currency_code, status FROM ${SCHEMA}.pool_definition
        WHERE status = 'A' ORDER BY pool_id LIMIT 1`,
      [],
      testCase
    );
  }
  if (!rows.length) {
    throw new Error(`[${testCase}] No active pool_id found in ${SCHEMA}.pool_definition`);
  }

  log(`[${testCase}] Pool Id from ${SCHEMA}.pool_definition: ${rows[0].pool_id} ` +
    `(currency=${rows[0].currency_code || '-'})`);
  return rows[0].pool_id;
}

/** Set field 31 (txnPoolId) in each OLSTXN DT record. */
function setDetailPoolId(content, poolId) {
  let changed = 0;
  const lines = String(content).split(/\r?\n/).map((line) => {
    if (!line.startsWith('DT|')) return line;
    const cells = line.split('|'); // cells[0]='DT', cells[31] = txnPoolId
    if (cells.length > 31 && poolId) {
      cells[31] = poolId;
      changed += 1;
    }
    return cells.join('|');
  });
  return { content: lines.join('\r\n'), changed };
}

/**
 * Get a transaction_code from ols_schema.transaction_code (status 'A'), preferring channel
 * 'BATCH' to match the file channel. Write it to field 2 (txnTranCode) of each DT record.
 */
export async function getTxnCode(testCase = 'OLSD134R') {
  let rows = await executeDbQuery(
    `SELECT transaction_code, description_english, channel_id FROM ${SCHEMA}.transaction_code
      WHERE status = 'A' AND channel_id = 'BATCH' ORDER BY transaction_code LIMIT 1`,
    [],
    testCase
  );
  if (!rows.length) {
    rows = await executeDbQuery(
      `SELECT transaction_code, description_english, channel_id FROM ${SCHEMA}.transaction_code
        WHERE status = 'A' ORDER BY transaction_code LIMIT 1`,
      [],
      testCase
    );
  }
  if (!rows.length) throw new Error(`[${testCase}] No transaction_code with status 'A' in ${SCHEMA}.transaction_code`);

  log(`[${testCase}] txn_code from ${SCHEMA}.transaction_code: ${rows[0].transaction_code} ` +
    `(${rows[0].description_english || '-'}, channel=${rows[0].channel_id || '-'})`);
  return rows[0].transaction_code;
}

/** Set field 2 (txnTranCode) in each DT record. */
function setDetailTxnCode(content, txnCode) {
  let changed = 0;
  const lines = String(content).split(/\r?\n/).map((line) => {
    if (!line.startsWith('DT|')) return line;
    const cells = line.split('|'); // cells[0]='DT', cells[2] = txnTranCode
    if (cells.length > 2 && txnCode) {
      cells[2] = txnCode;
      changed += 1;
    }
    return cells.join('|');
  });
  return { content: lines.join('\r\n'), changed };
}

/**
 * Set field 1 (txnTranType) in each DT record.
 * OLSDB009 requires txnTranType '01' in the OLSTXN file, not '03'.
 */
function setDetailTxnType(content, txnType) {
  let changed = 0;
  const lines = String(content).split(/\r?\n/).map((line) => {
    if (!line.startsWith('DT|')) return line;
    const cells = line.split('|'); // cells[0]='DT', cells[1] = txnTranType
    if (cells.length > 1 && txnType) {
      cells[1] = txnType;
      changed += 1;
    }
    return cells.join('|');
  });
  return { content: lines.join('\r\n'), changed };
}

/**
 * Find a product_account_no that does not exist in ols_schema.product_account.
 * This creates one rejected txn_type='01' DT record (BE108 - This Product Account does not
 * exist), because OLSD134R only lists rejected transactions.
 */
export async function getNonexistentAccountNo(testCase = 'OLSD134R') {
  for (let n = 1; n <= 999; n += 1) {
    const candidate = `99998${String(n).padStart(7, '0')}`;
    const rows = await executeDbQuery(
      `SELECT 1 FROM ${SCHEMA}.product_account WHERE product_account_no = $1 LIMIT 1`,
      [candidate],
      testCase
    );
    if (!rows.length) {
      log(`[${testCase}] Non-existent product account in ${SCHEMA}.product_account (for rejected record): ${candidate}`);
      return candidate;
    }
  }
  throw new Error(`[${testCase}] Cannot find any product_account_no that does not exist in ${SCHEMA}.product_account`);
}

/**
 * Add one DT record by cloning the first DT and applying field overrides. Update TR
 * recordCount (recordCount = N(DT) + 4).
 */
/**
 * Look up the input data required by the negative-case rule:
 *   txn_code = 'SICS645', pool_id = 'P1', and a product account whose PAT + PAL is in the
 *   PBDS of that pool (product_account.product_account_type || product_account_level =
 *   pool_definition.pbds_id).
 */
export async function getRulePoolContext(testCase = 'OLSD134R') {
  const pools = await executeDbQuery(
    `SELECT pool_id, pbds_id, currency_code FROM ${SCHEMA}.pool_definition WHERE pool_id = $1 LIMIT 1`,
    ['P1'],
    testCase
  );
  if (!pools.length) throw new Error(`[${testCase}] Pool 'P1' not found in ${SCHEMA}.pool_definition`);
  const pool = pools[0];

  const accounts = await executeDbQuery(
    // PBDS mapping: pool_definition.pbds_id -> pool_bucket_deduction_seq (PBDS) ->
    // product_account, joined on product account type + level (the PBDS account definition).
    `SELECT pa.product_account_no, pa.product_account_type, pa.product_account_level, pa.acct_curr_code
       FROM ${SCHEMA}.pool_definition pd
       JOIN ${SCHEMA}.pool_bucket_deduction_seq pbds
         ON pbds.pbds_id = pd.pbds_id
        AND pbds.status = 'A'
       JOIN ${SCHEMA}.product_account pa
         ON pa.product_account_type  = pbds.pbds_product_account_type
        AND pa.product_account_level = pbds.pbds_product_account_level
       WHERE pd.pool_id = $1
         AND pa.status = 'A'
      -- product_account_status is relaxed (preferred, not mandatory) so that at least two
      -- different accounts are returned for the negative fixtures.
      ORDER BY (pa.product_account_status = '1') DESC, pa.product_account_no
      LIMIT 2`,
    [pool.pool_id],
    testCase
  );
  if (!accounts.length) {
    // Do NOT abort the whole suite when the rule account cannot be resolved: the positive
    // cases (TC01-TC03) must keep running. Fall back to the base account and warn loudly so
    // the negative-case fixture can be reviewed later.
    log(`⚠️ [${testCase}] No product_account with PAT+PAL = pbds_id '${pool.pbds_id}' for pool P1 - ` +
      `fallback: clone the base DT account (rule input not verified)`);
    return { pool, account: null, accounts: [] };
  }

  log(`[${testCase}] Rule input: txn_code=SICS645, pool=${pool.pool_id} (pbds_id=${pool.pbds_id}), ` +
    `accounts=${accounts.map((a) => a.product_account_no).join(', ')}`);
  return { pool, account: accounts[0], accounts };
}

/**
 * Fill up to 2 accounts for the negative fixtures.
 *
 * The PBDS table (pool_bucket_deduction_seq) holds several product-account type/level pairs
 * per pool, so we walk those pairs and pick one active account for each - that gives two
 * DIFFERENT accounts (both satisfying "PAT+PAL in PBDS of the pool") for the txn_type=01 and
 * txn_type=03 fixtures, so their report keys do not collide.
 */
export async function fillRuleAccounts(ruleCtx, testCase = 'OLSD134R') {
  const accounts = [...(ruleCtx.accounts || [])];
  if (accounts.length >= 2) return accounts;

  const pairs = await executeDbQuery(
    `SELECT DISTINCT pbds_product_account_type AS pat, pbds_product_account_level AS pal
       FROM ${SCHEMA}.pool_bucket_deduction_seq
      WHERE pbds_id = $1 AND status = 'A'
        AND pbds_product_account_type IS NOT NULL
      ORDER BY pbds_product_account_type, pbds_product_account_level
      LIMIT 8`,
    [ruleCtx.pool.pbds_id],
    testCase
  );

  for (const pair of pairs) {
    if (accounts.length >= 2) break;
    const found = await executeDbQuery(
      `SELECT product_account_no, product_account_type, product_account_level, acct_curr_code
         FROM ${SCHEMA}.product_account
        WHERE product_account_type = $1
          AND product_account_level = $2
          AND status = 'A'
        ORDER BY (product_account_status = '1') DESC, product_account_no
        LIMIT 1`,
      [pair.pat, pair.pal],
      testCase
    );
    if (!found.length) continue;
    if (!accounts.some((a) => a.product_account_no === found[0].product_account_no)) {
      accounts.push(found[0]);
      log(`[${testCase}] Extra rule account from PBDS pair ${pair.pat}/${pair.pal}: ` +
        `${found[0].product_account_no}`);
    }
  }
  return accounts;
}

function appendRejectedDetail(content, overrides, description) {
  const lines = String(content).split(/\r?\n/);
  const dtIdx = lines.findIndex((l) => l.startsWith('DT|'));
  if (dtIdx < 0) return content;

  const cells = lines[dtIdx].split('|');
  for (const [index, value] of Object.entries(overrides)) cells[Number(index)] = value;
  const extraLine = cells.join('|');

  const out = lines.slice();
  out.splice(dtIdx + 1, 0, extraLine);

  const trIdx = out.findIndex((l) => l.startsWith('TR|'));
  if (trIdx >= 0) {
    const tr = out[trIdx].split('|');
    const dtCount = out.filter((l) => l.startsWith('DT|')).length;
    tr[68] = String(dtCount + 4).padStart(9, '0');
    out[trIdx] = tr.join('|');
  }

  log(`[OLSD134R] Added 1 rejected DT record: ${description}`);
  return out.join('\r\n');
}

/**
 * Get header dates from the DB to avoid BE301 (CreateDate older than the last run date)
 * and ensure that each file has a unique batch date.
 *   createDate = MAX(today, MAX(source_create_date))
 *   batchDate  = MAX(today, MAX(source_batch_date) + 1 day)
 * @returns {Promise<{createDate: string, batchDate: string, maxCreateDate: string, maxBatchDate: string}>}
 */
export async function getHeaderDates(testCase = 'OLSDB009') {
  const today = toYmd(new Date());
  const rows = await executeDbQuery(
    `SELECT to_char(MAX(source_create_date), 'YYYYMMDD') AS max_create,
            to_char(MAX(source_batch_date), 'YYYYMMDD')  AS max_batch,
            to_char(COALESCE(MAX(source_batch_date), CURRENT_DATE) + INTERVAL '1 day', 'YYYYMMDD') AS next_batch
       FROM ${SCHEMA}.batch_header
      WHERE file_id = $1`,
    [FILE_ID],
    testCase
  );

  const maxCreateDate = (rows[0] && rows[0].max_create) || null;
  const maxBatchDate = (rows[0] && rows[0].max_batch) || null;
  const nextBatchDate = (rows[0] && rows[0].next_batch) || null;

  const createDate = maxCreateDate && maxCreateDate > today ? maxCreateDate : today;
  const batchDate = nextBatchDate && nextBatchDate > today ? nextBatchDate : today;

  log(`[${testCase}] Header dates: createDate=${createDate} (MAX(source_create_date)=${maxCreateDate || '-'}), ` +
    `batchDate=${batchDate} (MAX(source_batch_date)=${maxBatchDate || '-'} + 1 day, unique for this file)`);

  return { createDate, batchDate, maxCreateDate, maxBatchDate };
}

/**
 * Step 1 - generate OLSTXN input using the OLSDB009 generator, upload it to the server,
 * and run ./OLSDB009 for back-end scoring.
 */
export async function prepareOlstxnInput(ctx, testCase = 'OLSD134R') {
  log(`[${testCase}] Prepare OLSTXN input with TXN_TYPE = ${TXN_TYPE_REDEMPTION}`);
  log(`[${testCase}] File OLSTXN dung txnTranType = ${TXN_TYPE_FILE} ` +
    `(report loc dwh_temp_txn.txn_type = ${TXN_TYPE_REDEMPTION})`);
  const generatedNames = await generateTestCase(ADJUSTMENT_SOURCE.testCase, {
    date: ctx.batchDateYmd,
    quiet: true,
  });

  fs.ensureDirSync(CONFIG.winscp.localPath);
  const sourceDir = path.join(__dirname, '..', 'test-data', 'generated', 'OLSDB009', ADJUSTMENT_SOURCE.testCase);

  // Get header dates from the DB: createDate >= last run date, batchDate >= MAX(source_batch_date),
  // and a unique batch date for each file (see getHeaderDates).
  const headerDates = await getHeaderDates(testCase);

  // Rename the file to identify it as OLSD134R seed data:
  //   OLSTXN-OLS-<date>-01.dat -> OLSTXN-<CONFIG.winscp.fileNameSource>-<date>-01.dat
  const source = CONFIG.winscp.fileNameSource || 'OLS';
  // BE302: (file_id + file_number + createDate) must be unique; BE051: the file name must be unused.
  const createIso = `${headerDates.createDate.slice(0, 4)}-${headerDates.createDate.slice(4, 6)}-${headerDates.createDate.slice(6, 8)}`;
  let seq = await getNextFileNumber(createIso, 'OLSDB009');
  for (;;) {
    const candidate = `OLSTXN-${source}-${ctx.batchDateYmd}-${String(seq).padStart(2, '0')}.dat`;
    if (!(await isFileNameUsed(candidate, 'OLSDB009'))) break;
    seq += 1;
  }
  log(`[OLSD134R] Next file_number for createDate=${headerDates.createDate}: ${seq} ` +
    `(avoid BE302 duplicate file_id + file_number + createDate)`);
  const fileNumber = String(seq).padStart(4, '0');
  const fileNames = [];
  for (const oldName of generatedNames) {
    const newName = oldName
      .replace(/^OLSTXN-[^-]+-/, `OLSTXN-${source}-`)
      .replace(/-\d{2}\.dat$/, `-${String(seq).padStart(2, '0')}.dat`);
    const raw = fs.readFileSync(path.join(sourceDir, oldName), 'utf8');
    const withDates = setDetailDates(raw, ctx.batchDateYmd);
    // Pool Id is required for txn_type='01'; get it from ols_schema.pool_definition.
    const dtLine = withDates.content.split(/\r?\n/).find((l) => l.startsWith('DT|'));
    const acctCurrency = dtLine ? (dtLine.split('|')[9] || null) : null; // field 9 = txnAcctCurrCode
    const poolId = await getPoolId(acctCurrency, testCase);
    const withPool = setDetailPoolId(withDates.content, poolId);
    // Get txn_code from ols_schema.transaction_code and write it to DT field 2.
    const txnCode = await getTxnCode(testCase);
    const withTxnCode = setDetailTxnCode(withPool.content, txnCode);
    // OLSTXN business rule: field 1 txnTranType must be '01' for OLSDB009.
    const withTxnType = setDetailTxnType(withTxnCode.content, TXN_TYPE_FILE);
    // Add one BE108 row (unknown product account) and one BE632 row (unknown product
    // account type) so the happy-case report verifies both rejection reasons.
    const nonExistentAccount = await getNonexistentAccountNo(testCase);
    // Negative cases: input that satisfies the rule (txn_code SICS645, pool P1, account
    // with PAT+PAL in the pool PBDS) but must NOT be printed by the OLSD134R report.
    const ruleCtx = await getRulePoolContext(testCase);
    const ruleAccounts = await fillRuleAccounts(ruleCtx, testCase);
    // Use two different accounts (both PAT+PAL in the pool PBDS, status A) so the report keys
    // of the txn_type=01 and txn_type=03 fixtures do not collide.
    const acctFor01 = ruleAccounts[0] || null;
    const acctFor03 = ruleAccounts[1] || acctFor01;
    const buildRuleOverrides = (acct) => ({
      2: '645',      // txnTranCode
      3: 'SICS',     // txnChannelId
      32: '',        // txnAdjReason must be blank for this rule input
      31: ruleCtx.pool.pool_id,
      ...(acct ? {
        5: acct.product_account_no,
        6: acct.product_account_type,
        7: acct.product_account_level,
        9: acct.acct_curr_code || 'MYR',
      } : {}),
    });
    const ruleAcctLabel = acctFor01 ? acctFor01.product_account_no : '(base account)';

    // TC04 - txn_type='03' WITH error_code: report only prints txn_type='01' -> must be absent
    const withTxnType03 = appendRejectedDetail(
      withTxnType.content,
      { ...buildRuleOverrides(acctFor03), 1: '03' },
      `TC04 negative: txn_type='03', txn_code=645, channel=SICS, pool=${ruleCtx.pool.pool_id}, ` +
      `acct=${acctFor03 ? acctFor03.product_account_no : '(base)'} (expect error_code IS NOT NULL)`
    );

    // TC05 - txn_type='01' WITHOUT error_code: report only prints error_code IS NOT NULL -> must be absent
    const withCleanTxn = appendRejectedDetail(
      withTxnType03,
      { ...buildRuleOverrides(acctFor01), 1: '01' },
      `TC05 negative: txn_type='01', txn_code=645, channel=SICS, pool=${ruleCtx.pool.pool_id}, ` +
      `acct=${ruleAcctLabel} (expect error_code IS NULL)`
    );

    const withUnknownAccount = appendRejectedDetail(
      withCleanTxn,
      { 5: nonExistentAccount },
      `BE108 candidate, txn_type='01', prod_acct_nbr=${nonExistentAccount} (not found in product_account)`
    );
    const withUnknownAccountType = appendRejectedDetail(
      withUnknownAccount,
      { 6: 'ZZZZZZZZ' },
      "BE632 candidate, txn_type='01', txnProdAcctType='ZZZZZZZZ' (not found in OLS)"
    );
    const patched = setHeaderDates(withUnknownAccountType, { ...headerDates, fileNumber });

    fs.writeFileSync(path.join(sourceDir, newName), patched);
    if (newName !== oldName) fs.removeSync(path.join(sourceDir, oldName));
    // Keep a local copy marked as OLSD134R seed data. The uploaded name must follow
    // the OLSTXN-<source>-... convention, so the copy is identified only locally.
    // Keep only the current run in the seed/push folder (otherwise it grows one file per run)
    fs.emptyDirSync(CONFIG.report.seedDir);
    fs.writeFileSync(path.join(CONFIG.report.seedDir, newName), patched);
    log(`[${testCase}] File seed/push cho OLSD134R: ${newName} ` +
      `(ban sao: ${path.join(CONFIG.report.seedDir, newName)}) ` +
      `(HD createDate=${headerDates.createDate}, batchDate=${headerDates.batchDate}, ` +
      `${withDates.changed} DT record txnTranDate=${ctx.batchDateYmd}, txnPoolId=${poolId}, ` +
      `txnTranCode=${txnCode}, txnTranType=${TXN_TYPE_FILE})`);
    fileNames.push(newName);
  }

  // File names are daily-use resources. If a name is already in the ledger, uploading it
  // again causes BE051 and the job fails, so report the condition clearly.
  const used = await findAlreadyImportedNames(fileNames);
  if (used.length) {
    log(`[${testCase}] ⚠️ File name already in batch_resource: ${used.join(', ')}`);
    log(`[${testCase}] ⚠️ Skip upload (avoid BE051). dwh_temp_txn keeps data from the previous run.`);
    return { uploaded: [], skipped: used, fileNames };
  }

  for (const name of fileNames) {
    const sourceFile = path.join(sourceDir, name);
    fs.copyFileSync(sourceFile, stagingPath(name));
    log(`[${testCase}] Copy ${name} -> ${CONFIG.winscp.localPath}`);
  }

  // Upload + run the batch. If the batch rejects the file because another upload took the
  // same file_number on the same create date (BE302 "duplicated with same date"), bump the
  // file number, patch the HD record and retry once.
  let uploadedNames = fileNames;
  let attempt = 0;
  // Other testers may upload OLSTXN files for the same date while we run, taking the next
  // file_number in batch_header. Re-read batch_header on every retry and take the next free
  // number/name instead of failing on the first BE302 / BE051.
  const MAX_ATTEMPTS = 4;
  for (;;) {
    try {
      await uploadFiles(uploadedNames, 'OLSDB009');
      await runRemoteBatch(ADJUSTMENT_SOURCE.batch, 'OLSDB009');
      break;
    } catch (error) {
      attempt += 1;
      if (attempt >= MAX_ATTEMPTS) throw error;

      let nextSeq = await getNextFileNumber(createIso, 'OLSDB009');
      for (;;) {
        const candidate = `OLSTXN-${source}-${ctx.batchDateYmd}-${String(nextSeq).padStart(2, '0')}.dat`;
        if (!(await isFileNameUsed(candidate, 'OLSDB009'))) break;
        nextSeq += 1;
      }
      const nextNumber = String(nextSeq).padStart(4, '0');
      log(`⚠️ [${testCase}] Batch rejected the file (attempt ${attempt}/${MAX_ATTEMPTS - 1}, ` +
        `likely BE302 duplicate file_number). Re-reading batch_header and retrying with ` +
        `file_number=${nextNumber}`);

      const retried = [];
      for (const oldName of uploadedNames) {
        const oldPath = path.join(sourceDir, oldName);
        const content = setHeaderDates(fs.readFileSync(oldPath, 'utf8'), { fileNumber: nextNumber });
        const newName = oldName.replace(/-\d{2,3}\.dat$/, `-${String(nextSeq).padStart(2, '0')}.dat`);
        fs.writeFileSync(path.join(sourceDir, newName), content);
        fs.writeFileSync(stagingPath(newName), content);
        fs.removeSync(oldPath);
        fs.removeSync(stagingPath(oldName));
        retried.push(newName);
        log(`[${testCase}] Retry file: ${oldName} -> ${newName} (HD fileNumber=${nextNumber})`);
      }
      uploadedNames = retried;
    }
  }

  return { uploaded: uploadedNames, skipped: [], fileNames: uploadedNames };
}

/**
 * Step 2 - after OLSDB009 completes, verify that rejected transactions were written to
 * dwh_temp_txn. Back-end scoring may finish after the batch exit code, so wait briefly
 * before concluding that no data was created.
 *
 * Return rejected redemption records as OLSD134R expected data.
 */
export async function verifyRejectedTransaction(ctx, {
  testCase = 'OLSDB009',
  fileNames = [],
  lastCutoffTime = null,
  timeoutMs = 120000,
  intervalMs = 5000,
} = {}) {
  log(`[${testCase}] Verify rejected transaction in DWH_TEMP_TXN ` +
    `(txn_type='${TXN_TYPE_REDEMPTION}', error_code IS NOT NULL, file ${fileNames.join(', ') || 'n/a'}` +
    `${lastCutoffTime ? `, process_date > last_cutoff_time ${lastCutoffTime}` : ''})`);

  const deadline = Date.now() + timeoutMs;
  let rows = [];
  let source = '';

  for (;;) {
    // Prefer the uploaded file because it identifies the current data directly.
    rows = fileNames.length ? await fetchRejectedRedemptionsByFileName(fileNames, testCase) : [];
    source = 'file_name';
    if (!rows.length) {
      rows = await fetchRejectedRedemptions(ctx, testCase, lastCutoffTime);
      source = `cua so process_date cua report (${ctx.fromDate} -> ${ctx.toDate}` +
        `${lastCutoffTime ? `, > last_cutoff_time ${lastCutoffTime}` : ''})`;
    }
    if (rows.length || Date.now() >= deadline) break;
    await new Promise((resolve) => setTimeout(resolve, intervalMs));
  }

  if (!rows.length) {
      log(`[${testCase}] ⚠️ No rejected redemption transaction for file ` +
      `${fileNames.join(', ') || '(no file)'} and none in the batch process_date window ` +
      `(${ctx.fromDate} -> ${ctx.toDate}) after ${Math.round(timeoutMs / 1000)}s. OLSD134R report will be empty.`);
    return rows;
  }

  log(`[${testCase}] Rejected transaction found: ${rows.length} row(s) (source: ${source})`);
  for (const row of rows.slice(0, 5)) {
    log(`[${testCase}]  File: ${row.file_name || 'n/a'} | Batch ID: ${row.batch_id} | ` +
      `Process Date: ${toIsoDate(row.process_date)} | ` +
      `Product Acct Number: ${row.prod_acct_nbr} | Maintenance Date: ${row.maintenance_date} | ` +
      `Branch ID: ${row.branch_id} | Sign: ${row.txn_sign} | Amount: ${row.txn_amt}`);
    log(`[${testCase}]  Error Code: ${row.error_code}`);
    log(`[${testCase}]  Error Message: ${row.error_message}`);
  }
  if (rows.length > 5) log(`[${testCase}]  ... and ${rows.length - 5} more row(s)`);

  return rows;
}

// ============ REPORT/DASHBOARD DATA ============
// All rows from the uploaded file, including rejected rows, are used to capture
// the Post Date and import result for that file.
export async function fetchTransactionsByFileName(fileNames, testCase = 'OLSDB009') {
  if (!fileNames.length) return [];

  const sql = `SELECT dtt.id, dtt.file_name, dtt.line_number, dtt.txn_type, dtt.txn_code,
      dtt.prod_acct_nbr, dtt.prod_acct_level, dtt.prod_acct_type, dtt.acct_curr_code,
      dtt.txn_sign, dtt.txn_amt, dtt.branch_id, dtt.txn_date, dtt.txn_time,
      to_char(dtt.process_date, 'YYYY-MM-DD HH24:MI:SS') AS process_date,
      to_char(dtt.maintenance_date, 'YYYY-MM-DD HH24:MI:SS') AS maintenance_date,
      dtt.error_code, dtt.error_message, dtt.valid, dtt.status, dtt.process_status
    FROM ${SCHEMA}.dwh_temp_txn dtt
    WHERE dtt.file_name = ANY($1::text[])
    ORDER BY dtt.id`;

  return executeDbQuery(sql, [fileNames], testCase);
}

/** Return the latest process_date among rows from the uploaded file. */
export async function getPostDate(fileNames, testCase = 'OLSDB009') {
  if (!fileNames.length) return null;
  const rows = await executeDbQuery(
    `SELECT to_char(MAX(dtt.process_date), 'YYYY-MM-DD HH24:MI:SS') AS post_date
       FROM ${SCHEMA}.dwh_temp_txn dtt WHERE dtt.file_name = ANY($1::text[])`,
    [fileNames],
    testCase
  );
  return rows.length && rows[0].post_date ? rows[0].post_date : null;
}

/** Return the report cut-off from oe_cutofftime_control (column names verified on dev). */
export async function getCutoffTimes(testCase = 'OLSDR134') {
  const rows = await executeDbQuery(
    `SELECT module_id,
            to_char(last_cutoff_time, 'YYYY-MM-DD HH24:MI:SS')    AS last_cutoff_time,
            to_char(current_cutoff_time, 'YYYY-MM-DD HH24:MI:SS') AS current_cutoff_time,
            control_cutoff_time
       FROM ${SCHEMA}.oe_cutofftime_control WHERE module_id = ANY($1)`,
    [CUTOFF_MODULE_IDS],
    testCase
  );

  for (const moduleId of CUTOFF_MODULE_IDS) {
    const found = rows.find((r) => String(r.module_id).trim() === moduleId);
    if (found) return found;
  }
  return null;
}

/**
 * Update the report cut-off BEFORE running the report (OLSD134R business requirement):
 *   current_cutoff_time = batch date - 1 day (23:59:59)
 *   last_cutoff_time    = current_cutoff_time - 1 day (23:59:59)
 *
 * The report lists only transactions with process_date > last_cutoff_time, so these values
 * ensure that it scans the correct data window for the batch date under test.
 */
export async function updateCutoffTimes(ctx, testCase = 'OLSD134R') {
  await executeDbQuery(
    `UPDATE ${SCHEMA}.oe_cutofftime_control
        SET last_cutoff_time    = ($1::date - 2) + time '23:59:59',
            last_cutoff_by      = $2,
            current_cutoff_time = ($1::date - 1) + time '23:59:59',
            current_cutoff_by   = $2
      WHERE module_id = $3`,
    [ctx.batchDate, testCase, CUTOFF_MODULE_IDS[0]],
    testCase
  );

  const rows = await getCutoffTimes(testCase);
  log(`[${testCase}] Updated cut-off (module ${CUTOFF_MODULE_IDS[0]}): ` +
    `last_cutoff_time=${rows ? rows.last_cutoff_time : 'n/a'}, ` +
    `current_cutoff_time=${rows ? rows.current_cutoff_time : 'n/a'} ` +
    `(batch date ${ctx.batchDate})`);
  return rows;
}

/** Batch output files in the input directory: <file>_<pid>_<batchdate>.{out,rej} and OLSDB009_*.err. */
export async function listBatchOutputs(fileNames, testCase = 'OLSDB009') {
  const result = { files: [], out: [], rej: [], err: [] };
  if (!fileNames.length) return result;

  const bases = fileNames.map((n) => n.replace(/\.dat$/i, ''));
  const grepArgs = bases.map((b) => `-e '${b}'`).join(' ');
  const stdout = await executeRemoteCommand(
    `ls -1 ${CONFIG.winscp.remotePath} | grep -F ${grepArgs} || true`,
    testCase
  );

  result.files = String(stdout).split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
  for (const file of result.files) {
    if (file.endsWith('.out')) result.out.push(file);
    else if (file.endsWith('.rej')) result.rej.push(file);
    else if (file.endsWith('.err')) result.err.push(file);
  }
  return result;
}

/** Count DT records in output files (.out = imported, .rej = rejected). */
export async function countDtRows(files, testCase = 'OLSDB009') {
  if (!files.length) return 0;
  const paths = files.map((f) => `${CONFIG.winscp.remotePath}${f}`).join(' ');
  const stdout = await executeRemoteCommand(`grep -h '^DT|' ${paths} 2>/dev/null | wc -l`, testCase);
  return Number(String(stdout).trim()) || 0;
}

/** Wait for OLSDB009 output files (step 5) and count their results (step 6). */
export async function waitForBatchOutputs(fileNames, {
  testCase = 'OLSDB009',
  add = () => {},
  timeoutMs = 180000,
  intervalMs = 5000,
} = {}) {
  const deadline = Date.now() + timeoutMs;
  let outputs = await listBatchOutputs(fileNames, testCase);

  while (!outputs.files.length && Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, intervalMs));
    outputs = await listBatchOutputs(fileNames, testCase);
  }

  outputs.dtOutRows = await countDtRows(outputs.out, testCase);
  outputs.dtRejRows = await countDtRows(outputs.rej, testCase);

  add('5', 'Wait for OLSDB009 output files', true,
    outputs.files.length
      ? `${outputs.files.length} output file(s): ${outputs.files.join(', ')}`
      : 'no output file yet');

  add('6', 'Verify OLSDB009 output files (.dat/.rej/.err)', outputs.files.length > 0,
    outputs.files.length
      ? `out=${outputs.out.length} (${outputs.dtOutRows} DT), rej=${outputs.rej.length} ` +
        `(${outputs.dtRejRows} DT), err=${outputs.err.length}`
      : 'no .out/.rej/.err found for the uploaded file (file may be rejected before import)');

  return outputs;
}

/**
 * Run the full data-preparation flow: OLSTXN (txn_type 01) -> OLSDB009 -> verify
 * rejected records in dwh_temp_txn.
 * Return steps, outputs, postDate, and cut-offs for test-runner.spec.js.
 * @returns {Promise<{ctx: Object, rejected: Array, steps: Array, outputs: Object, postDate: string, cutoffs: Object, transactions: Array}>}
 */
export async function prepareData(testCase = 'OLSD134R') {
  const steps = [];
  const add = (no, name, ok, note = '', extra = {}) => {
    steps.push({ no: String(no), name, ok: Boolean(ok), note, ...extra });
    log(`[STEP ${no}] ${ok ? '✅' : '❌'} ${name}${note ? ' — ' + note : ''}`);
    return true;
  };

  log(`[${testCase}] === Start preparing data for OLSD134R ===`);
  // Step 0: set batch_date = CURRENT_DATE before running OLSDB009.
  const batchDateUpdate = await updateBatchDate(testCase);
  if (batchDateUpdate) {
    add('0', 'Update batch_date = current date (before OLSDB009)', true,
      `record_no=${batchDateUpdate.after ? batchDateUpdate.after.record_no : 'n/a'} | ` +
      `before=${batchDateUpdate.before ? batchDateUpdate.before.batch_date : 'n/a'} -> ` +
      `after=${batchDateUpdate.after ? batchDateUpdate.after.batch_date : 'n/a'} | ` +
      `processing_date=${batchDateUpdate.after ? batchDateUpdate.after.processing_date : 'n/a'}`,
      {
        sql: `UPDATE ${SCHEMA}.batch_date
   SET batch_date = CURRENT_DATE, processing_date = CURRENT_DATE - 1,
       last_update_date = now(), last_update_by = 'OLSD134R'
 WHERE record_no = (SELECT MAX(record_no) FROM ${SCHEMA}.batch_date);`,
      });
  }
  const ctx = await getBatchContext(testCase);
  log(`[${testCase}] batch date = ${ctx.batchDateYmd}, cut-off = ${ctx.cutOffTime} (module ${ctx.cutOffModuleId})`);
  log(`[${testCase}] data window (process_date): > ${ctx.fromDate} AND <= ${ctx.toDate}`);

  const prepared = await prepareOlstxnInput(ctx, testCase);
  const fileNames = prepared.fileNames || [];

  add('1', 'Copy OLSTXN files to local src folder', prepared.uploaded.length > 0 || prepared.skipped.length > 0,
    prepared.uploaded.length
      ? `${prepared.uploaded.join(', ')} -> ${CONFIG.winscp.localPath}`
      : `skipped (name already in ledger: ${prepared.skipped.join(', ')})`);
  add('2', 'Upload files via WinSCP to SFTP', prepared.uploaded.length > 0,
    prepared.uploaded.length
      ? `${prepared.uploaded.join(', ')} -> ${CONFIG.winscp.remotePath}`
      : 'not uploaded (avoid BE051)');
  add('3', 'Run OLSDB009 batch', true, `cd ${CONFIG.batch.scriptPath} && ./${ADJUSTMENT_SOURCE.batch}`);
  add('4', 'Wait for OLSDB009 to complete', true, 'batch finished (exit code 0)');

  const outputs = await waitForBatchOutputs(fileNames, { add, testCase: 'OLSDB009' });

  // Step 8a - update the cut-off before running the report:
  //   current_cutoff_time = batch date - 1 day, last_cutoff_time = current - 1 day
  const cutoffsBefore = await getCutoffTimes(testCase);
  const cutoffs = await updateCutoffTimes(ctx, testCase);
  add('8a', 'Update oe_cutofftime_control (last_cutoff_time=BD-2, current_cutoff_time=BD-1)', true,
    `module_id='${CUTOFF_MODULE_IDS[0]}' | before: last=${cutoffsBefore ? cutoffsBefore.last_cutoff_time : 'n/a'}, ` +
    `current=${cutoffsBefore ? cutoffsBefore.current_cutoff_time : 'n/a'} | after: ` +
    `last=${cutoffs ? cutoffs.last_cutoff_time : 'n/a'}, current=${cutoffs ? cutoffs.current_cutoff_time : 'n/a'} ` +
    `(batch date ${ctx.batchDate})`,
    {
      sql: `UPDATE ${SCHEMA}.oe_cutofftime_control
   SET last_cutoff_time    = ('${ctx.batchDate}'::date - 2) + time '23:59:59',
       last_cutoff_by      = 'OLSD134R',
       current_cutoff_time = ('${ctx.batchDate}'::date - 1) + time '23:59:59',
       current_cutoff_by   = 'OLSD134R'
 WHERE module_id = '${CUTOFF_MODULE_IDS[0]}';`,
    });

  // OLSD134R does not display records with process_date <= last_cutoff_time.
  const lastCutoffTime = cutoffs ? cutoffs.last_cutoff_time : null;

  const rejected = await verifyRejectedTransaction(ctx, { fileNames, lastCutoffTime, add });
  const transactions = await fetchTransactionsByFileName(fileNames, 'OLSDB009');
  const postDate = await getPostDate(fileNames, 'OLSDB009');

  if (transactions.length) {
    const t = transactions[0];
    add('7', 'Check DWH_TEMP_TXN rows of this file & save Post_Date', true,
      `file=${t.file_name}, txn_type=${t.txn_type}, error_code=${t.error_code || '(null)'}, ` +
      `Post_Date=${postDate || '(null)'}`,
      {
        sql: `SELECT * FROM ${SCHEMA}.dwh_temp_txn WHERE file_name = '${t.file_name}' ORDER BY id;`,
        rows: transactions,
        rowsLabel: `${transactions.length} row(s) — first row captured below | Post_Date = ${postDate || '(null)'}`,
      });
  } else {
    add('7', 'Check DWH_TEMP_TXN rows of this file & save Post_Date', false,
      'no dwh_temp_txn row for the uploaded file (file rejected before import)');
  }

  if (postDate && cutoffs) {
    add('8', `Check cutoff time - oe_cutofftime_control (module_id='${cutoffs.module_id}')`, true,
      `last_cutoff_time = ${cutoffs.last_cutoff_time} | current_cutoff_time = ${cutoffs.current_cutoff_time} | ` +
      `report filter: process_date > last_cutoff_time`,
      {
        sql: `SELECT * FROM ${SCHEMA}.oe_cutofftime_control WHERE module_id = '${cutoffs.module_id}';`,
        rows: [cutoffs],
      });

    const gtLast = postDate > cutoffs.last_cutoff_time;
    const gtCurrent = postDate > cutoffs.current_cutoff_time;
    const greater = gtLast && gtCurrent;
    add('9', 'Verify Post_Date is greater than both last_cutoff_time and current_cutoff_time', greater,
      `Post_Date = ${postDate} must be GREATER THAN last_cutoff_time (${cutoffs.last_cutoff_time}) ` +
      `and current_cutoff_time (${cutoffs.current_cutoff_time}) | ` +
      `Post_Date > last_cutoff_time = ${gtLast} | Post_Date > current_cutoff_time = ${gtCurrent} | ` +
      `result = ${greater ? 'GREATER THAN CUTOFF' : 'NOT GREATER THAN CUTOFF'}`);
  } else {
    add('8', 'Check cutoff time - oe_cutofftime_control', false,
      `cut-off=${cutoffs ? 'found' : 'no cut-off row'}`);
    add('9', 'Verify Post_Date is greater than both cutoff times', false,
      `Post_Date=${postDate || '(null)'}, cut-off=${cutoffs ? 'found' : 'no cut-off row'}`);
  }

  log(`[${testCase}] === Seed data completed ===`);
  return { ctx, rejected, steps, outputs, postDate, cutoffs, transactions };
}

// ============ CLI ============
// Run directly: node scripts/OLSD134R/file-generator.js
const isDirectRun =
  process.argv[1] && path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url));

if (isDirectRun) {
  prepareData('CLI')
    .then(({ ctx, rejected }) => {
      log('Done. Data is ready for the OLSD134R report.', {
        batchDate: ctx.batchDateYmd,
        rejectedRecords: rejected.length,
      });
      process.exit(0);
    })
    .catch((error) => {
      console.error(`❌ ${error.message}`);
      process.exit(1);
    });
}
